INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('ampsphere','AMPSphere','https://ampsphere.big-data-biology.org/','GET','Just as the ecosphere is the worldwide sum of all ecosystems, the AMPsphere comprises the complexity of prokaryotic AMPs assembled in one dataset. To date, we analyzed the 86k high-quality genomes in proGenomes2, and over 63k metagenomes from ENA, NCBI and JGI. After redundancy removal, we produced a collection of AMPs from the global microbiome, containing 863,498 distinct sequences, clustered into 10,715 AMP families with at least 7 sequences each.','AMPsphere comprises the complexity of prokaryotic AMPs, combining publicly available metagenomes and high-quality isolated microbial genomes.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('ANA','THANATOS','http://thanatos.biocuckoo.org/','GET','Cell death especially Programmed cell-death (or PCD) is critical for development and health of multicellular organisms. Previously, apoptosis is identified to be the primary mechanism while cells are eliminated physiologically in metazoan organisms or plants (Kerr et al., 1972). Recently, in contrast to traditionally consideration as a simple way to die, necrosis has emerged as an alternate form of programmed cell death (Proskuryakov et al., 2003). Furthermore, besides its functions as a survival strategy under stress, autophagy was considered to be another programmed cell death (Tsujimoto and Shimizu et al., 2005). During the last several decades, numerous studies were contributed to characterize these biological processes, especially apoptosis, which was previously considerd to be an anti-cancer mechanism (Hickman et al., 1992). Recent studies suggested that necrosis and autophagy might also be implicated in tumor supression (Proskuryakov et al., 2003; Maycotte and Thorburnet al., 2011), while defect of these cell death processes usually lead to cancer (Hickman et al., 1992; Edinger and Thompsonet al., 2003). From the literatures in PubMed, we have curated the experimentally identified proteins which regulate apoptosis, necrosis and/or autophagy (THANATOS) from S. cerevisiae, C. elegans, D. melanogaster, M. musculus , R. norvegicus, D. rerio, A. thaliana, and H. sapiens. Furthermore, ortholog searches were performed in 164 eukaryotes. Then the integrated and searchable database THANATOS (THe Autophagy, Necrosis, ApopTosis OrchestratorS) was established. Currently, the THANATOS database was updated on May 07, 2017, containing 191,543 unique protein entries. The database will be updated routinely as new thanatos proteins are reported.','THe Autophagy, Necrosis, ApopTosis OrchestratorS',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('Animal-SNPAtlas','Animal-SNPAtlas','http://gong_lab.hzau.edu.cn/Animal_SNPAtlas/','GET',NULL,'Animal-SNPAtlas: a comprehensive SNP database for multiple animals.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('animalAPAdb','animalAPAdb','http://gong_lab.hzau.edu.cn/Animal-APAdb/','GET','A comprehensive animal alternative polyadenylation database','A comprehensive animal alternative polyadenylation database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('animaleRNAdb','animaleRNAdb','http://gong_lab.hzau.edu.cn/Animal-eRNAdb/','GET','A comprehensive animal enhancer RNA database','A comprehensive animal enhancer RNA database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('animaltfdb','AnimalTFDB','http://bioinfo.life.hust.edu.cn/AnimalTFDB4/','GET','AnimalTFDB is a comprehensive database including classification and annotation of genome-wide transcription factors (TFs) and transcription cofactors in 183 animal genomes. In AnimalTFDB v4.0, there are total 270k TFs which are further classified into 73 families and six categories based on their DNA-binding domain (DBD). Meanwhile, there are also 150k cofactors classified into 82 families and six categories.','Animal Transcription Factor Database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('bbcancer','BBCancer','http://bbcancer.renlab.org/','GET','BBCancer is a web-accessible and comprehensive open resource for providing the expression landscape of six type of RNAs, including messenger RNAs(mRNAs), Long non-coding RNAs(lncRNAs), microRNAs(miRNAs), circular RNAs(circRNAs), tRNA derived fragments(tRFRNAs) and Piwi-interacting RNAs(piRNAs) in 7184 samples including 5040 blood samples such as extracellular vesicles (EVs) and circulating tumor cells (CTCs) from normal persons or cancer patients of 15 cancer types.','BBCancer: an expression atlas of blood-based biomarkers in the early diagnosis of cancers',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('cancersea','CancerSEA','http://biocc.hrbmu.edu.cn/CancerSEA/','GET','ScRNA-seq provides an unprecedented opportunity to explore the functional heterogeneity of cancer cells. CancerSEA is the first dedicated database that aims to comprehensively decode distinct functional states of cancer cells at single-cell resolution.','CancerSEA: a cancer single-cell state atlas',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('cellmarker','CellMarker','http://xteam.xbio.top/CellMarker/','GET','One of the most fundamental questions in biology is which types of cells form different tissues and organs in a functionally coordinated fashion. Larger-scale single cell sequencing and biology experiment studies are now rapidly opening up new ways to track this question by revealing substantial cell markers for distinguishing different cell types in tissues. Here, we developed the CellMarker databases, aiming to provide a comprehensive and accurate resource of cell markers for various cell types in tissues of human and mouse.','CellMarker: a manually curated resource of cell markers in human and mouse.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('cgdb','CGDB','http://cgdb.biocuckoo.org/','GET','CGDB (Circadian Gene DataBase) is an online resource containing over 72,800 genes in more than 148 organisms that exhibit (or may exhibit) daily oscillation at the transcript level.','Circadian Gene Database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('CGGA','CGGA','http://cgga.org.cn','GET','a user-friendly web application for data storage and analysis to explore brain tumors datasets over 2,000 samples from Chinese cohorts','Chinese Glioma Genome Atlas',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('circAltas','circAltas','http://circaltas.biols.ac.cn','GET','An integrated resource of circRNAs in vertebrates.','circAtlas 2.0',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('consrm','ConsRM','http://180.208.58.19/conservation/index.html','GET','A novel scoring framework, ConsRM, was devised to quantitatively measure the degree of conservation of individual m6A RNA methylation sites. ConsRM integrates positional mapping, tissue-specific mapping, support from multiple studies, sequence similarity, genome conservation and a positive-unlabeled learning model, which integrated 63 genomic features as well sequence features to trace epitranscriptome layer conservation.','Collection and large-scale prediction of the evolutionarily conserved RNA methylation sites, with implications for the functional epitranscriptome.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('cplm','CPLM Database','https://cplm.biocuckoo.cn','GET','A comprehensive resource for Protein Lysine Modifications.','Compendium of Protein Lysine Modifications Database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('dbpaf','dbPAF','http://dbpaf.biocuckoo.org/','GET','The dbPAF (database of Phospho-sites in Animals and Fungi) is an online data resource specifically designed for protein phosphorylation in seven eukaryotic species, including H. sapiens, M. musculus, R. norvegicus, D. melanogaster, C. elegans, S. pombe and S. cerevisiae.','database of Phospho-sites in Animals and Fungi',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('dbppt','dbPPT','http://dbppt.biocuckoo.org/','GET','As one of the most important and ubiquitous post-translational modifications (PTMs) in plants, the reversible phosphorylation catalyzed by protein kinases is involved in regulating a wide range of biological processes such as cellular metabolism, signal transduction and environmental response (Ranjeva et al., 1987; Mundy et al., 2002; Kusakina et al., 2012). Recently with the development of phosphopeptide enrichment techniques and high-throughput mass spectrometry (HTP-MS) technology, large scale phosphoproteomics data in plants have been emerged at a quick pace, stimulating the creation of multiple phosphorylation databases to store and organize them. However, a more comprehensive phosphorylation database of plants is still necessary and useful. In this work, we develop a database of dbPPT 1.0 (database of Phospho-sites in PlanTs), which contains large-scale phosphorylation sites (p-sites) based on mass spectrometry across 20 plant species. Most of the datasets in dbPPT 1.0 were manually curated from literature published before July, 2014. Moreover, we also integrated other phosphorylation resource into this database including PhosPhAt (Durek et al., 2010) and P3DB (Yao et al., 2014). Currently, dbPPT contains 82,175 p-sites in 31,012 proteins for 20 plant species.','database of Phospho-sites in PlanTs',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('dbpsp','dbPSP','http://dbpsp.biocuckoo.cn/','GET','In prokaryotes, protein phosphorylation plays a critical role in regulating a broad spectrum of biological processes and occurs mainly on various amino acids, including serine (S), threonine (T), tyrosine (Y), arginine (R), aspartic acid (D), histidine (H) and cysteine (C) residues of protein substrates. Through literature curation and public database integration, here we reported an updated database of phosphorylation sites (p-sites) in prokaryotes (dbPSP 2.0) that contains 19,296 experimentally identified p-sites in 8,586 proteins from 200 prokaryotic organisms, which belong to 12 phyla of two kingdoms, bacteria and archaea. To carefully annotate these phosphoproteins and p-sites, we integrated the knowledge from 88 publicly available resources that covers 9 aspects, namely, taxonomy annotation, genome annotation, function annotation, transcriptional regulation, sequence and structure information, family and domain annotation, interaction, orthologous information and biological pathway. In contrast to version 1.0 (~30 MB), dbPSP 2.0 contains ~9 GB of data, with a 300-fold increased volume. We anticipate that dbPSP 2.0 can serve as a useful data resource for further investigating phosphorylation events in prokaryotes. dbPSP 2.0 is free for all users to access at: http://dbpsp.biocuckoo.cn.','database of Phosphorylation Sites in Prokaryotes',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('deg','DEG','http://tubic.org/deg/','GET',NULL,'Database of Essential Genes',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('directrmdb','directRMDB','http://www.rnamd.org/directRMDB/index.html','GET','The first ONT-based database of quantitative RNA modification profiles, DirectRMDB, which includes 16 types of modification and a total of 904,712 modification sites in 25 species identified from 39 independent studies. In addition to standard functions adopted by existing databases, such as gene annotations and post-transcriptional association analysis, we provide a fresh view of RNA modifications, which enables exploration of the epitranscriptome in an isoformspecific manner.','A ONT-based database of quantitative RNA modification profiles.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DiseaseEnhancer','DiseaseEnhancer','http://biocc.hrbmu.edu.cn/DiseaseEnhancer/','GET','Genetic alterations/variants of enhancers make an essential contribution to disease progression. And more than 3 million of enhancers generated by international consortiums indicated that disease-associated enhancers will open a brand new view of pathophysiology. DiseaseEnhancer provides a comprehensive map of manually curated disease-associated enhancers, which includes 1059 disease-associated enhancers in 167 human diseases, involving 896 unique enhancer-gene interactions. We also manually collected their dysregulated target genes and mechanistic-related information, such as the associated variant types (including single nucleotide variant, somatic mutation, indel and copy number alteration) and affected transcription factor bindings. Additional genome data were also integrated into DiseaseEnhancer to help characterize disease-associated enhancers.','DiseaseEnhancer: a resource of human disease-associated enhancer catalog.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_AlphaMissense','DMS_AlphaMissense','https://idc.biosino.org/dms/dictionary/view/85','GET',NULL,'AlphaMissense achieves state-of-the-art missense pathogenicity predictions in clinical annotation, de novo disease variants, and experimental assay benchmarks without explicitly training on such data.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_BV_BRC_bacteria','DMS_BV_BRC_bacteria','https://idc.biosino.org/dms/dictionary/view/92','GET',NULL,'The Bacterial and Viral Bioinformatics Resource Center (BV-BRC) is an information system designed to support research on bacterial and viral infectious diseases. BV-BRC combines two long-running BRCs: PATRIC, DMS_BV_BRC_bacteria is the bacterial system, and IRD/ViPR',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
