INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_CEBIO','DMS_Chemical Entities of Biological Interest Ontology','https://idc.biosino.org/dms/dictionary/view/12','GET',NULL,'Chemical Entities of Biological Interest (ChEBI) is a freely available dictionary of molecular entities focused on ‘small’ chemical compounds. ',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_ClinGen','DMS_ClinGen','https://idc.biosino.org/dms/dictionary/view/86','GET',NULL,'ClinGen is a National Institutes of Health (NIH)-funded resource dedicated to building a central resource that defines the clinical relevance of genes and variants for use in precision medicine and research.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_Clinvar','DMS_ClinVar','https://idc.biosino.org/dms/dictionary/view/57','GET',NULL,'ClinVar aggregates information about genomic variation and its relationship to human health.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_CMO','DMS_Clinical Measurement Ontology','https://idc.biosino.org/dms/dictionary/view/13','GET',NULL,'The Clinical Measurement Ontology is designed to be used to standardize morphological and physiological measurement records generated from clinical and model organism research and health programs.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_COSMIC','DMS_COSMIC','https://idc.biosino.org/dms/dictionary/view/58','GET',NULL,'COSMIC, the Catalogue Of Somatic Mutations In Cancer, is the world''s largest and most comprehensive resource for exploring the impact of somatic mutations in human cancer.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_DECIPHER','DMS_DECIPHER','https://idc.biosino.org/dms/dictionary/view/87','GET',NULL,'DECIPHER is used by the clinical community to share and compare phenotypic and genotypic data.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_DiseaseOntology','DMS_DiseaseOntology','https://idc.biosino.org/dms/dictionary/view/49','GET',NULL,'The Disease Ontology has been developed as a standardized ontology for human disease with the purpose of providing the biomedical community with consistent, reusable and sustainable descriptions of human disease terms, phenotype characteristics and related medical vocabulary disease concepts through collaborative efforts of biomedical researchers, coordinated by the University of Maryland School of Medicine, Institute for Genome Sciences.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_DoCM','DMS_DoCM','https://idc.biosino.org/dms/dictionary/view/84','GET',NULL,'DoCM is a curated repository that facilitates the aggregation of gene and variant information for variants with prognostic, diagnostic, predictive, or functional roles from these resources as well as from individually curated publications',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_Drugbank','DMS_Drugbank','https://idc.biosino.org/dms/dictionary/view/41','GET',NULL,'a comprehensive, free-to-access, online database containing information on drugs and drug targets.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_Drugtarget','DMS_Drugtarget','https://idc.biosino.org/dms/dictionary/view/25','GET',NULL,'Drug (i.e. chemical, pharmacological and pharmaceutical) data with comprehensive drug target (i.e. sequence, structure, and pathway) information.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_Ecoli_gene','DMS_Ecoli_gene','https://idc.biosino.org/dms/dictionary/view/29','GET',NULL,'The EcoGene database provides a set of gene and protein sequences derived from the genome sequence of Escherichia coli K-12. ',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_eLMSG','DMS_eLMSG','https://idc.biosinno.org/dms/dictionary/view/28','GET','The eLMSG database is intended to integrate microbial systematics, genomics and phenomics (polyphasic taxonomy related phenotypes). It will enclose information on taxonomy, ecology, morphology, physiology, and molecular biology, etc.',NULL,1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_Ensembl','DMS_Ensembl','https://idc.biosino.org/dms/dictionary/view/56','GET',NULL,'Ensembl supports research in comparative genomics, evolution, sequence variation and transcriptional regulation. Ensembl annotate genes, computes multiple alignments, predicts regulatory function and collects disease data.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_EnvironmentOntology','DMS_EnvironmentOntology','https://idc.biosino.org/dms/dictionary/view/99','GET',NULL,'ENVO is a domain ontology concerned with "environments" of all kinds and aims to promote standardisation and interoperability of diverse data sets through the concise, controlled description of environment types across several levels of granularity',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_GenCC','DMS_GenCC','https://idc.biosino.org/dms/dictionary/view/89','GET',NULL,'The GenCC DB provides information pertaining to the validity of gene-disease relationships, with a current focus on Mendelian diseases. ',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_Gene4Denovo','DMS_Gene4Denovo','https://idc.biosino.org/dms/dictionary/view/83','GET',NULL,'Gene4Denovo provided a convenient interface for non-commercial users to freely search, browse, analysis, and download any data in the database. Most importantly, Gene4Denovo allows users to upload their genetic variants, identify co-segregated variants including DNMs, perform custom annotations, and prioritized pathogenetic variants and risk-genes. In summary, Gene4denovo bring great convenience to accelerate the interpretation of the pathogenicity and clinical implication of DNMs for geneticists, neurobiologists and clinicians.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_Gene4MND','DMS_Gene4MND','https://idc.biosino.org/dms/dictionary/view/82','GET',NULL,'Motor neuron disease (MND) refers to several types of neurodegenerative disorders characterized by affecting upper and lower motor neurons, rapidly progressive weakness leading to paralysis and eventually death from respiratory failure. Gene4MND is a dedicated repository, platform and communication warehouse for MND that aims to accelerate genetic consulting, enhance the understanding of the diseases and facilitate MND research.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_Gene4PD','DMS_Gene4PD','https://idc.biosino.org/dms/dictionary/view/81','GET',NULL,'Gene4PD, including following knowledge: (1) rare variants identified from PD patients, (2) copy-number variants (CNVs), (3) associated SNPs collected from GWAS, (4) differential expression genes, and (5) differential DNA methylation genes. Based on these different category data, Gene4PD prioritized a list of candidate genes with variant genetic evidences for further characterization.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_GTDB','DMS_GTDB','https://idc.biosino.org/dms/dictionary/view/80','GET',NULL,'The Genome Taxonomy Database (GTDB) is an initiative to establish a standardised microbial taxonomy based on genome phylogeny, primarily funded by the Australian Research Council via a Laureate Fellowship (FL150100038), a Future Fellowship (FT170100213), and Discovery Project (DP220100900), with the welcome assistance of strategic funding from The University of Queensland.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_HGNC','DMS_HGNC','https://idc.biosino.org/dms/dictionary/view/55','GET',NULL,'The HGNC is responsible for approving unique symbols and names for human loci, including protein coding genes, ncRNA genes and pseudogenes, to allow unambiguous scientific communication.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_HPO','DMS_Human Phenotype Ontology','https://idc.biosino.org/dms/dictionary/view/2','GET',NULL,'The Human Phenotype Ontology (HPO) provides a standardized vocabulary of phenotypic abnormalities encountered in human disease. Each term in the HPO describes a phenotypic abnormality, such as Atrial septal defect. The HPO is currently being developed using the medical literature, Orphanet, DECIPHER, and OMIM. HPO currently contains over 13,000 terms and over 156,000 annotations to hereditary diseases. ',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_ICD-10','DMS_ICD-10','https://idc.biosino.org/dms/dictionary/view/34','GET',NULL,'International Classification of Diseases 10th Revision. The global standard for diagnostic health information.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
