INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_ICD-10-PCS','DMS_ICD-10-PCS','https://idc.biosino.org/dms/dictionary/view/47','GET',NULL,'ICD-10-PCS is a totally new coding system designed to better accommodate the rapidly changing world of procedures. ICD-10-PCS provides a multi-axial design to the codes and is similar in design to Logical Observation Identifiers Names and Codes (LOINC).',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_ICD-11','DMS_ICD-11','https://idc.biosino.org/dms/dictionary/view/48','GET',NULL,'International Classification of Diseases 11th Revision. The global standard for diagnostic health information.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_ICD-9','DMS_ICD-9','https://idc.biosino.org/dms/dictionary/view/44','GET',NULL,'International Classification of Diseases 9th Revision. The global standard for diagnostic health information.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_ICD-9-CM','DMS_ICD-9-CM','https://idc.biosino.org/dms/dictionary/view/45','GET',NULL,'The International Classification of Diseases, 9th Revision, Clinical Modification (ICD-9-CM) is based on the World Health Organization’s Ninth Revision, International Classification of Diseases (ICD-9). ICD-9-CM is the official system of assigning codes to diagnoses and procedures associated with hospital utilization in the United States.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_ICD-9-IN','DMS_ICD-9-IN','https://idc.biosino.org/dms/dictionary/view/46','GET',NULL,'International Classification of Diseases 9th Revision. The global standard for diagnostic health information.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_KEGG-Otholog','DMS_KEGG-Otholog','https://idc.biosino.org/dms/dictionary/view/59','GET',NULL,'The KO (KEGG Orthology) database is a database of molecular functions represented in terms of functional orthologs.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_mc3','DMS_mc3','https://idc.biosino.org/dms/dictionary/view/21','GET',NULL,'Multi-Center Mutation Calling in TCGA Multiple Cancers project',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_Medgen','DMS_Medgen','https://idc.biosino.org/dms/dictionary/view/90','GET',NULL,'MedGen is NCBI''s portal to information about conditions and phenotypes related to Medical Genetics. Terms from the NIH Genetic Testing Registry (GTR), UMLS, HPO, Orphanet, ClinVar and other sources are aggregated into concepts, each of which is assigned a unique identifier and a preferred name and symbol. The core content of the record may include names, identifiers used by other databases, mode of inheritance, clinical features, and map location of the loci affecting the disorder. ',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_MeSH','DMS_MeSH','https://idc.biosino.org/dms/dictionary/view/54','GET',NULL,'MeSH (Medical Subject Headings) is the NLM controlled vocabulary thesaurus used for indexing articles for PubMed.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_OMIM','DMS_OMIM','https://idc.biosino.org/dms/dictionary/view/60','GET',NULL,'Online Mendelian Inheritance in Man is a continuously updated catalog of human genes and genetic disorders and traits, with particular focus on the molecular relationship between genetic variation and phenotypic expression.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_Ontobee','DMS_Ontobee','https://idc.biosino.org/dms/dictionary/view/100','GET',NULL,'Ontobee is a linked ontology data server that stores ontology information using RDF triple store technology and supports query, visualization and linkage of ontology terms and is also the default linked data server for publishing and browsing biomedical ontologies in the Open Biological Ontology (OBO) Foundry (OBO) library.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_PMO','DMS_PMO','https://idc.biosino.org/dms/dictionary/view/43','GET',NULL,'a standardized ontology for human precision medicine with consistent, reusable and sustainable descriptions of human disease terms, genomic molecular, phenotype characteristics and related medical vocabulary disease concepts through collaborative efforts of researchers at Institute of Medical Information, Chinese Academy of Medical Sciences.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_ProteinOntology','DMS_ProteinOntology','https://idc.biosino.org/dms/dictionary/view/11','GET',NULL,'PRO provides an ontological representation of protein-related entities by explicitly defining them and showing the relationships between them. Each PRO term represents a distinct class of entities (including specific modified forms, orthologous isoforms, and protein complexes) ranging from the taxon-neutral to the taxon-specific (e.g. the entity representing all protein products of the human SMAD2 gene is described in PR:Q15796; one particular human SMAD2 protein form, phosphorylated on the last two serines of a conserved C-terminal SSxS motif is defined by PR:000025934).',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_PubChem_BioAssays','DMS_PubChem_BioAssays','https://idc.biosino.org/dms/dictionary/view/73','GET',NULL,'PubChem BioAssay contains small-molecule and RNAi screening data along with associated annotation information from contributing organizations. BioAssay contains a collection of bioactivity and toxicity data that has greatly supported research in fields such as medicinal chemistry, drug discovery, pharmaceutical genomics and informatics research. ',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_PubChem_Compounds','DMS_PubChem_Compounds','https://idc.biosino.org/dms/dictionary/view/75','GET',NULL,'pubChem is an open archive accepting information from many sources about a given molecule, it is imperative to provide the end-user with an aggregated view of all that is known for a single chemical structure.  PubChem Compound records are derived summaries that give users access to a rich set of related content.  Compound records contain unique chemical structures extracted from contributed Substance records through a process called ‘standardization’.  Each Compound record points to at least one Substance record.  In contrast, a Substance record might have no derived Compound record if the structure cannot be standardized or is missing.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_PubChem_Substance','DMS_PubChem_Substance','https://idc.biosino.org/dms/dictionary/view/74','GET',NULL,'PubChem Substance is the primary archive for community-provided information about chemical entities.  A Substance record can contain any combination of chemical structures, synonyms, registration IDs, descriptions, related URLs, patent identifiers, database cross-references to PubMed, protein 3D structures, and biological screening results to name a few.  ',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_SFARI','DMS_SFARI','https://idc.biosino.org/dms/dictionary/view/79','GET',NULL,'SFARI Gene is an evolving database for the autism research community that is centered on genes implicated in autism susceptibility.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_SnomedCT_International','DMS_SnomedCT_International','https://idc.biosino.org/dms/dictionary/view/37','GET',NULL,'SNOMED International determines global standards for health terms, an essential part of improving the health of humankind. We are committed to maintaining and growing our leadership as the global experts in healthcare terminology, ensuring SNOMED CT is the global language for clinical terms.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_SnomedCT_US','DMS_SnomedCT_US','https://idc.biosino.org/dms/dictionary/view/36','GET',NULL,'The SNOMED CT United States (US) Edition is the official source of SNOMED CT for use in US healthcare systems. The US Edition is a standalone release that combines the content of both the US Extension and the International releases of SNOMED CT.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_Swissprot','DMS_Swissprot','https://idc.biosino.org/dms/dictionary/view/19','GET',NULL,'UniProtKB/Swiss-Prot is the expertly curated component of UniProtKB (produced by the UniProt consortium). It contains hundreds of thousands of protein descriptions, including function, domain structure, subcellular location, post-translational modifications and functionally characterized variants.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DMS_VirusHostDB','DMS_VirusHostDB','https://idc.biosino.org/dms/dictionary/view/91','GET',NULL,'Virus-Host DB organizes data about the relationships between viruses and their hosts, represented in the form of pairs of NCBI taxonomy IDs for viruses and their hosts. Virus-Host DB covers viruses with complete genomes stored in 1) NCBI/RefSeq and 2) GenBank whose accession numbers are listed in EBI Genomes or INPHARED. The host information is collected from RefSeq, GenBank (in free text format), UniProt, ViralZone, and manually curated with additional information obtained by literature surveys.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('DNAbcM','Common Microbial DNA Barcode Reference Library','https://mdc.im.ac.cn/microxiandao/dnabar','GET',NULL,'The Common Microbial DNA Barcode Reference Database curates microbial DNA barcode sequences along with their taxonomic information. Each record links a sequence to a clear taxonomic hierarchy that includes sample ID, species, family, and class. The platform enables advanced retrieval (by keywords, sample ID, lineage, etc.) and batch downloading of raw sequences.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('doric','DoriC','http://tubic.org/doric/','GET',NULL,'Database of Replication Origins',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('drllps','Drllps Database','https://llps.biocuckoo.cn','GET','A data resource of liquid-liquid phase separation in eukaryotes.','Liquid-liquid phase separation in eukaryotes Database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('ekpd','EKPD','http://ekpd.biocuckoo.org/','GET','The EKPD 1.1 contained 61,729 unique protein entries including 50,433 protein kinases and 11,296 protein phosphatases.','Eukaryotic Kinase and Phosphatase Database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('epsd','EPSD','http://epsd.biocuckoo.cn/','GET','The Eukaryotic Phosphorylation Site Database (EPSD) is a comprehensive data resource updated from two databases of dbPPT (Cheng, et al., 2014) and dbPAF (Ullah, et al., 2016), which contained 82,175 p-sites of 20 plants and 483,001 p-sites of 7 animals and fungi, respectively. EPSD contains 1,616,804 experimentally identified p-sites in 209,326 phosphoproteins from 68 eukaryotes.','Eukaryotic Phosphorylation Site Database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('EVEA','Extracellular Vesicle Atlas','http://bioinfo.life.hust.edu.cn/EVAtlas/','GET','EVAtlas provides four functional modules: (i) browse and compare the distribution of ncRNAs in EVs from 24 conditions and eight sources (plasma, serum, saliva, urine, sperm, breast milk, primary cell and cell line ); (ii) prioritize candidate ncRNAs in condition related tissues based on their expression; (iii) explore the specifically expressed ncRNAs in EVs from 24 conditions; (iv) investigate ncRNA functions, related drugs, target genes and EVs isolation methods.','In EVAtlas, we performed a unified read dynamic assignment algorithm (RDAA) considering mismatch and multi-mapping reads to quantify the expression profiles of seven ncRNA types (miRNA, snoRNA, piRNA, snRNA, rRNA, tRNA and Y RNA) in more than 2,030 high-quality small RNA-seq datasets of EV samples from 24 human tissues of different conditions (disease and normal).',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('evmirna','EVmiRNA','http://bioinfo.life.hust.edu.cn/EVmiRNA/','GET','Extracellular vesicles (EVs) released by living cells include exosomes and microvesicles (MVs), which contain various molecules from parental cells and are potential sources for disease diagnostic and therapeutic biomarkers. miRNA is the most well-studied molecule type in EVs because of its important functions and biomarker properties. Thus, we build the Extracellular Vesicles miRNA database (EVmiRNA) to collect comprehensive miRNA expression profiles in EVs. In EVmiRNA database, we analyzed 462 smRNA sequencing datasets of EVs from 17 tissues/diseases. The miRNA expression profiles, miRNA regulated pathways, miRNA function, miRNA related drugs and publications are showed to support the miRNA biomarker discovery.','EVmiRNA is a database of miRNA profiling in extracellular vesicles',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('genekang','VarClear','https://www.varclear.com','GET','VarClear锛屼腑鏂囧悕锛氭竻鐐癸紝鏄叧鑱斿熀鍥犲彉寮備笌瑙ｈ璇佹嵁鐨勪氦浜掑紡鏁版嵁搴撱�佺煡璇嗗簱銆�','Gene Variation Interpretation Database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('gentree','GenTree','http://gentree.ioz.ac.cn/','GET',' GenTree is designed to enable users to evaluate when and how a gene arises and what type of function it may have. For now, GenTree is the only systematical resource for new gene origination mainly in human and several other species. Ages of genes were inferred across species through a synteny-based pipeline. In human, Gene origination mechanism were also inferred and functional genomic data for new genes were complied.','GenTree, the time tree of genes along the evolutionary history',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('gmsc','GMSC','https://gmsc.big-data-biology.org/','GET','The global microbial smORF catalogue (GMSC) is an integrated, consistently-processed, smORFs catalogue of the microbial world, combining publicly available metagenomes and high-quality isolated microbial genomes.A total of non-redundant ~965 million 100AA ORFs were predicted from 63,410 metagenomes from global habitats and 87,920 high-quality isolated microbial genomes from the ProGenomes database. The smORFs were clustered at 90% amino acid identity resulting in ~288 million 90AA smORFs families.','The global microbial smORF catalogue (GMSC) is an integrated, consistently-processed, smORFs catalogue of the microbial world, combining publicly available metagenomes and high-quality isolated microbial genomes.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('hgmt','HGMT','https://mai.fudan.edu.cn/hgmt','GET','HGMT is a comprehensive database of the multi-kingdom gut microbiota from pan-tumor patients, which contains a rich collection of tumor-related biomarker taxa. Our efforts have led to the standardized processing of 16,195 treatment-naive human fecal samples, encompassing 35 WGS, 67 16S, and 3 ITS from 99 projects of 32 tumor types.','HGMT: deciphering the landscape of human gut microbiota in pan-tumor',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('HGNC','HGNC','https://idc.biosinno.org/dms/dictionary/view/55','GET',NULL,'The HGNC is responsible for approving unique symbols and names for human loci, including protein coding genes, ncRNA genes and pseudogenes, to allow unambiguous scientific communication.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('hPEA','Platelets expression atlas','http://bioinfo.life.hust.edu.cn/PEA/','GET','PEA provides a comprehensive repertoire of gene and miRNA expression profiles and advanced analysis results of each dataset: 1) Expression profiles of platelet in different diseases; 2) Average expression of a specified gene (miRNA) in health and various diseases; 3) Differential expression analysis, including functional enrichment of DEGs and protein-protein interaction network; 4) Platelet specifically expressed genes analysis.','Platelet Expression Atlas (PEA) is a comprehensive expression resource and functional analysis platform for human platelets',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('hTFtarget','hTFtarget','http://bioinfo.life.hust.edu.cn/hTFtarget/','GET','Transcription factors (TFs) are key regulators in gene expression from DNA to mRNA by binding to specific DNA sequences on promoters and enhancers to activate or repress specific gene expressions. They play key roles in biological processes and disease occurrence by controlling the spatial and temporal-specific expression of genes. Thus identifying the target genes of TFs is very important in the study of gene expression regulation, development and disease pathogenesis. In this hTFtarget database, we collected comprehensive human TF ChIP-Seq data and customized an analysis workflow to identify reliable TF targets with taking epigenomic states into account.','In this hTFtarget database, we collected comprehensive human TF ChIP-Seq data and customized an analysis workflow to identify reliable TF targets with taking epigenomic states into account',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('icellomics','iCellomics','https://ngdc.cncb.ac.cn/icellomics/','GET',NULL,'iCellOmics is an open-access, multi-omics resource for industrially relevant cell lines. Currently, iCellOmics integrates 6 data categories across 17 cell lines, including reference genome annotations, genomic variation, bulk and single-cell transcriptomics profiles, chromatin accessibility maps, and gene–phenotype relationships curated from the literature. ',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('iekpd','iEKPD','http://iekpd.biocuckoo.org/','GET','The database iEKPD (integrated annotations for Eukaryotic protein Kinases, protein Phosphatases & phosphoprotein-binding Domains, ver 2.0) contained 197,348 phosphorylation regulators, including 109,912 protein kinases, 23,294 protein phosphatases and 68,748 PPBD-containing proteins in 164 eukaryotic species. Moreover, iEKPD provided rich annotations for the regulators of eight model organisms, especially humans, by compiling and integrating the knowledge from 100 widely used public databases that cover 13 aspects, including cancer mutations, genetic variations, disease-associated information, mRNA expression, DNA & RNA elements, DNA methylation, molecular interactions, drug-target relations, protein 3D structures, post-translational modifications, protein expressions/proteomics, subcellular localizations and protein functional annotations.','Integrated annotations for Eukaryotic protein Kinases, protein Phosphatases & phosphoprotein-binding Domains',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('imp','IMP','https://www.bic.ac.cn/IMP','GET',NULL,'Intergrated Medicinal Plantomics',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('ipangolin','iPangolin','https://ngdc.cncb.ac.cn/ipangolin/','GET',NULL,'iPangolin is the first integrated, multi-dimensional database dedicated to pangolins, the world’s most trafficked and critically endangered mammalian group. ',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('ipcd','iPCD','http://ipcd.biocuckoo.cn/','GET','Programmed cell death (PCD) is an essential biological process involved in many human pathologies. According to the continuous discovery of new PCD forms, a large number of proteins have been found to regulate PCD. However, an integrative resource has yet to be established for maintaining these regulatory proteins. Here, we briefly summarize the mainstream PCD forms, as well as the current progress in the development of public databases to collect, curate and annotate PCD proteins. Also, we developed a comprehensive database, integrated annotations for programmed cell death (iPCD), which contained 1,091,014 regulatory proteins involved in 30 PCD forms across 562 eukaryotic species. From the scientific literature, we manually collected 6,493 experimentally identified PCD proteins, and an orthologous search was then conducted to computationally identify more potential PCD proteins. Additionally, we provided an in-depth annotation of PCD proteins in 8 model organisms, by integrating the knowledge from 102 additional resources that covered 16 aspects, including genetic variation and mutation, functional annotation, structural annotation, physicochemical property, functional domain, post-translational modification, disease-associated information, protein-protein interaction, drug-target relation, orthologous information, biological pathway, transcriptional regulator, mRNA expression, protein expression/proteomics, subcellular localization and DNA & RNA element. With a data volume of 125 GB, we anticipate that iPCD can serve as a highly useful resource for further analysis of PCD in eukaryotes.','database of PCD regulators',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('iuucd','iUUCD','http://iuucd.biocuckoo.org/','GET','The released iUUCD (integrated annotations for Ubiquitin and Ubiquitin-like Conjugation Database, ver 2.0) is an updated systematic resource for ubiquitin and ubiquitin-like conjugations. 27 E1s, 109 E2s, 1,153 E3s, 164 DUBs, 396 UBDs and 183 ULDs were collected from scientific literatures and classified into 1, 4, 23, 8, 27, 11 families, respectively. The newly release added 6 new families for E2, E3 and DUB enzymes, as well as a hierarchical classification for UBD and ULD families. Specially, detailed annotations for all these proteins were integrated from additional 68 public databases in 11 aspects as follows: (i) Cancer Mutation, including ICGC, COSMIC, TCGA, CGAP and IntOGen; (ii) Single Nucleotide Polymorphism (SNP), such as dbSNP; (iii) mRNA Expression, including GEO, ArrayExpress, GXD, FFGED, TCGA, ICGC, COSMIC, HUMAN PROTEOME MAP and The Human Protein Atlas; (iv) DNA & RNA Element, including UTRdb, AREsite, JASPAR CORE, circBase, circRNADb, CircNet, Circ2Traits, miRTarBase, microRNA.org, TRANSFAC, miRWalk, TargetScan, miRecords, RepTar, miRNAMap, SomamiR DB 2.0, miRcode, RAID v2.0 and LncRNADisease; (v) Protein-protein Interaction, including IID, iRefIndex, PINA, HINT, Mentha, SZDB and InWeb_IM; (vi) Protein 3D Structure, including PDB, MMDB and SCOP; (vii) Disease-associated Variation, including ClinVar, OMIM, GWASdb and GWAS CENTRAL; (viii) Drug-target Relation, including DrugBank, TTD, KPID, CARLSBAD, SuperTarget, GRAC and PDTD; (ix) Post-translational Modifications (PTMs), including CPLM, dbPAF, dbPPT, phosSNP, PhosphositePlus, Phospho.ELM, dbPTM, PHOSIDA, BioGRID, HPRD, UniProt, O-GlycBase, PhosphoBase and mUbiSiDa; (x) DNA Methylation, including MethyCancer, TCGA, ICGC and COSMIC; (xi) Protein Expression/Proteomics, including The Human Protein Atlas, Human Proteome Map and GPMDB. All in all, from 148 eukaryotic species, 136,512 proteins were identified and annotated as unique entries in iUUCD.','integrated annotations for Ubiquitin and Ubiquitin-like Conjugation Database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('LeukemiaDB','LeukemiaDB','http://bioinfo.life.hust.edu.cn/LeukemiaDB/','GET','In detail, there are 14 leukemia types, 53 leukemia cell lines, and 92 normal samples. Through analysis by unique pipeline, we obtained comprehensive information for transcriptomes of human leukemia, including: expression for protein-coding genes, long non-coding RNAs, and circular RNAs, as well as events for gene fusion and alternative splicing. Additionally, we processed TCGA AML data (TCGA-LAML) for survival and drug response analysis. Users can browse the database by modules / diseases / cell lines and search gene on each page.','LeukemiaDB collects 3068 samples in 188 leukemia-associated RNA-seq datasets from NCBI GEO and SRA. ',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('lncar','lnCAR','https://lncar.renlab.org/','GET','lnCAR is a comprehensive database that specifically dedicated to display differential expression profiles and prognostic landscape in human cancers by re-annotating microarray probes. At present, there are 10 cancer types and more than 54,000 samples collected in lnCAR (bladder cancer, breast cancer, cervical cancer, colorectal cancer, esophageal tumor, gastric cancer, liver cancer, lung cancer, ovarian cancer and prostatic cancer). Differential expression analysis, survival analysis, co-expression analysis, KEGG pathway enrichment analysis, ceRNA analysis and meta-analysis were integrated to explore the function of interested lncRNAs (including annotated lncRNAs or any user-defined ones). In addition to basic transcript information, structure and conservative score, we also integrated low-throughput data, such as real-time PCR and northern blot, into lnCAR as validation datasets. Furthermore, multiple statistical diagrams are also embedded in the web server for visualizing the analysis results.','lnCAR | A comprehensive resource for lncRNAs from Cancer Arrays',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('lncbook','LncBook','https://bigd.big.ac.cn/lncbook','GET','LncBook is a curated knowledgebase of human lncRNAs that features a comprehensive collection of human lncRNAs and systematic curation of lncRNAs by multi-omics data integration, functional annotation and disease association. The current implementation of LncBook houses a large number of 270,044 lncRNAs and includes 1,867 featured lncRNAs with 3,762 lncRNA-function associations. It also integrates an abundance of multi-omics data from expression, methylation, genome variation and lncRNA-miRNA interaction. In addition, LncBook includes 3,772 experimentally validated lncRNA-disease associations and identifies a total of 97,998 lncRNAs that are putatively disease-associated. To facilitate online analysis, a series of useful tools such as coding potential prediction, sequence search, etc., are deployed in LncBook.','A curated knowledgebase of human long non-coding RNAs.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('lncrnadisease','LncRNADisease','http://www.rnanut.net/lncrnadisease/','GET','Long noncoding RNAs (lncRNAs) represent the RNAs that have a size of >200 nucleotides and lack the capability of protein-coding. Although lncRNAs are among one of the least well-understood molecules, emerging studies have revealed that lncRNAs play critical roles in a broad range of biological processes and are associated with a number of diseases, i.e. cancer, cardiovascular disease, and neurodegeneration disease. LncRNAs are becoming critically important for the understanding of life sciences, especially diseases. The LncRNADisease database is not only a resource that curated the experimentally supported lncRNA-disease association data but also a platform that integrated tool(s) for predicting novel lncRNA-disease associatons. In addition, LncRNADisease also curated lncRNA interactions in various levels, including protein, RNA, miRNA, and DNA.','LncRNA diseases interaction database.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('lncRNASNP v3','lncRNASNP v3','http://gong_lab.hzau.edu.cn/lncRNASNP3/','GET',NULL,'lncRNASNP v3: a comprehensive resources for functional variants in long non-coding RNAs.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('lncrnasnp2','lncRNASNP2','http://bioinfo.life.hust.edu.cn/lncRNASNP2','GET',NULL,NULL,1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('m5catlas','m5C-Atlas','http://180.208.58.19/m5c-atlas/index.html','GET','The database contains 166,540 m5C sites in 13 species identified from 5 base-resolution epitranscriptome profiling technologies. Moreover, condition-specific methylation levels are quantified from 351 RNA bisulfite sequencing samples gathered from 22 different studies via an integrative pipeline. The database also presents several novel features, such as the evolutionary conservation of a m5C locus, its association with SNPs, and any relevance to RNA secondary structure.','A database for comprehensive collection and annotation of RNA 5-methylcytosine.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('m6Aatlas2','m6A-Atlas v2.0','http://rnamd.org/m6a/index.php','GET','m6A-Atlas v2.0 was expanded to include 797,091 reliable m6A sites among 7 species, with 13 high-resolution technologies and 109 conditions. Additionally, sites derived from single-cell technique were presented for the first time. Besides high-resolution data, 16,868,200 m6A enriched regions were recorded in the updated version from 2,712 MeRIP-seq samples.','A comprehensive knowledgebase for unraveling the N6-methyladenosine (m6A) epitranscriptome.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('m6AConquer','m6AConquer','https://rnamd.org/m6aconquer/','GET','m6AConquer integrates 10 sequencing technologies with unified quantification, orthogonal IDR-based validation, and multi-omics integration including transcriptomics, splicing and m6A QTLs.','A consistently quantified and orthogonally validated database for the m6A epitranscriptome.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('m6atshub','m6A-TSHub','http://180.208.58.19/tshub/index.html','GET','We present here a comprehensive online platform, m6A-TSHub, for unveiling the context-specific m6A methylation and genetic mutations that potentially regulate m6A epigenetic mark.  m6A-TSHub consists of four core components, including (1) m6A-TSDB, a comprehensive database of 184,554 functionally annotated m6A sites derived from 23 human tissues and 499,369 m6A sites from 25 tumor conditions, respectively;  (2) m6A-TSFinder, a web server for high-accuracy prediction of m6A methylation sites within a specific tissue from RNA sequences, which was constructed using multi-instance deep neural networks with gated attention;  (3) m6A-TSVar, a web server for assessing the impact of genetic variants on tissue-specific m6A RNA modifications;  and (4) m6A-CAVar, a database of 587,983 The Cancer Genome Atlas (TCGA) cancer mutations (derived from 27 cancer types) that were predicted to affect m6A modifications in the primary tissue of cancers.','Unveiling thedynamics of the N6-methyladenosine(m6A) epitranscriptome.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('m7ghub2','m7GHub V2.0','http://www.rnamd.org/m7GHub2/index.html','GET','The four main components presented in the first release have all been expanded: an m7GDB database containing 430,898 putative m7G sites identified in 23 species, collected from both widely applied next-generation sequencing (NGS) and the emerging Oxford Nanopore direct RNA sequencing (ONT) techniques; an m7GDiseaseDB hosting 156,206 m7G-associated variants (involving addition or removal of an m7G site), including 3,238 disease-relevant m7G-SNPs that may function through epitranscriptome disturbance; and two enhanced analysis modules to perform interactive analyses on the collections of m7G sites (m7GFinder) and functional variants (m7GSNPer). We expect that m7Ghub v2.0 should serve as a valuable centralized resource for studying m7G modification.','An updated resource for a comprehensive collection of m7G modifications in various types of RNAs across multiple species.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('MCK','MiCroKiTS','http://microkit.biocuckoo.org/','GET','During cell cycle, numerous proteins temporally and spatially localized in distinct sub-cellular regions including centrosome (spindle pole in budding yeast), kinetochore/centromere, cleavage furrow/midbody (related or homolog structures in plants and budding yeast called as phragmoplast and bud neck, respectively), telomere and spindle spatially and temporally. These sub-cellular regions play important roles in various biological processes. In this work, we have collected all proteins identified to be localized on kinetochore, centrosome, midbody, telomere and spindle from two fungi (S. cerevisiae and S. pombe) and five animals, including C. elegans, D. melanogaster, X. laevis, M. musculus and H. sapiens based on the rationale of Seeing is believing (Bloom K et al., 2005). Through ortholog searches, the proteins potentially localized at these sub-cellular regions were detected in 144 eukaryotes. Then the integrated and searchable database MiCroKiTS - Midbody, Centrosome, Kinetochore, Telomere and Spindle has been established. Currently, the MiCroKiTS 4.0 database was updated on Sep. 6, 2014, containing 87,983 unique protein entries. The database will be updated routinely as new microkits proteins are reported.','Midbody, Centrosome, Kinetochore, Telomere and Spindle',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('methbankCrm','Methbank CRMs','https://bigd.big.ac.cn/methbank/crms/','GET','450K data from GEO and TCGA, Consensus Reference Methylomes (CRMs)','Methbank, Consensus Reference Methylomes (CRMs)',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('methbankSrm','MethBank SRMs','https://bigd.big.ac.cn/methbank/srms/','GET','Single-base Resolution Methylomes (SRMs)','Methbank, Single-base Resolution Methylomes (SRMs)',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('mirnasnp','miRNASNP-v3','http://bioinfo.life.hust.edu.cn/miRNASNP/','GET','In miRNASNP-v3, 46,826 SNPs in human 1,897 pre-miRNAs (2,624 mature miRNAs) and 7,115,796  SNPs in 3''UTRs of 18,151 genes were characterized. Besides, 505,417 disease-related variations (DRVs) from GWAS, ClinVar and COSMIC were identified in miRNA and gene 3''UTR. Gene enrichment of target gain/loss by variations in miRNA seed region was provided.','miRNASNP-v3 is a comprehensive database for SNPs and disease-related variations in miRNAs and miRNA targets',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('mmdb','MMDB','http://bigd.big.ac.cn/mmdb','GET','China is a large agricultural country, sustainable and stable agricultural products production has a very important strategic significance for ensuring food security in China. The seed is the source of food production. With the rapid development of life sciences, biotechnological breeding has become an inevitable choice for the development of modern seed industry. The status of breeding technology in China had put forward the concept of "designer breeding by molecular modules", the development construction of“innovation systems of designer breeding by molecular modules”could lead to a revolution in biotechnological breeding.
