INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('openac4c','OpenAc4C','https://www.rnamd.org/ac4cportal/','GET','OpenAc4C is an integrated resource for ac4C RNA modification. It includes NGS acRIP-seq regions, NGS high-resolution sites, direct RNA sequencing-derived putative ac4C sites, ac4C-associated variants, and web-based analysis tools.','A gateway to decode the landscape, regulation and pathogenesis of N4-acetylcytidine (ac4C) epitranscriptome.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('padsarsenal','PADS Arsenal','https://bigd.big.ac.cn/padsarsenal','GET','PADS (Prokaryotic Antiviral Defense System) Arsenal is a database of prokaryotic antiviral defense system, which archived genes that are associated with 18 distinctive categories of defense systems. It is dedicated to gathering, storing, analyzing and visualizing prokaryotic defense gene datasets. It also provides the function of multiple sequence alignment and conservative analysis for these defense genes in various species from pan-genome insights.','PADS Arsenal is a database of prokaryotic antiviral defense system',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
