INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('plmd','PLMD','http://plmd.biocuckoo.org/','GET','PLMD (Protein Lysine Modifications Database) is an online data resource specifically designed for protein lysine modifications (PLMs) including 284,780 modification events in 53,501 proteins across 176 eukaryotes and prokaryotes for up to 20 types of PLMs.','Protein Lysine Modifications Database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('poxvirus','MPoxVR','https://ngdc.cncb.ac.cn/gwh/poxvirus','GET','The Monkeypox Virus Resource (MPoxVR) is a one-stop monkeypox virus (MPXV) resource and portal that features virus genome sequences, genomic variations, related literatures, raw sequencing data and online tools.','The Monkeypox Virus Resource (MPoxVR) is a one-stop monkeypox virus (MPXV) resource and portal',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
