INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('pwas atlas','PWAS Atlas','https://ngdc.cncb.ac.cn/pwas/','GET',NULL,'PWAS Atlas (https://ngdc.cncb.ac.cn/pwas/) is a comprehensive knowledgebase that systematically integrates publicly available proteome-wide association study (PWAS) findings with large-scale standardized analyses. ',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('rhesusbaseGenes','RhesusBase Genes','http://rhesusbase.com','GET',NULL,NULL,1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('rmdisease2','RMDisease V2.0','http://www.rnamd.org/rmdisease2/index.html','GET','An updated database with expanded coverage. Using deep learning models and from 873,819 experimentally-validated RNA modification sites, we identified a total of 1,366,252 RNA modification (RM)-associated variants that may affect (add or remove RM site) 16 different types of RNA modification (m6A, m5C, m1A, m5U, <ce><a8>, m6Am, m7G, A-to-I, ac4C, Am, Cm, Um, Gm, hm5C, D and f5C) in 20 organisms (human, mouse, rat, zebrafish, maize, fruit fly, yeast, fission yeast, Arabidopsis, rice, chicken, goat, sheep, pig, cow, rhesus monkey, tomato, chimpanzee, green monkey and COVID-19).','An updated database of genetic variants that affect RNA modifications with disease and trait implication',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('rmvar_v2','RMVar v2.0','https://rmvar.renlab.cn/','GET',NULL,'Database of functional variants involved in RNA modifications',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('scrapdb','ScRAPdb','https://evomicslab.org/db/ScRAPdb/','GET','Telomere-to-Telomere (T2T) Saccharomyces cerevisiae reference assemblies and population-scale pan-omics data','Saccharomyces cerevisiae Reference Assembly Panel Database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('SEECancer','SEECancer','http://biocc.hrbmu.edu.cn/SEECancer/','GET','Cancer is driven by accumulating somatic alterations which confer normal cells fitness advantage to evolve from a premalignant status to malignant tumor. The SEECancer database presents the comprehensive cancer evolutionary stage-specific somatic events (including early-specific, late-specific, relapse-specific, metastasis-specific, drug-resistant and drug-induced genomic events) and their temporal orders.','SEECancer: a resource for somatic events in evolution of cancer genome.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('SEGreg','SEGreg','http://bioinfo.life.hust.edu.cn/SEGreg','GET','The specifically expressed genes (SEGs) only expressed in unique or a small number of tissues/conditions provide important clues about the gene and tissue-specific biological functions. SEGs may serve as potential biomarkers for disease diagnosis and treatment. The identification of SEGs will be helpful to globally and dynamically understand the gene functions and their roles in biological processes. However, the mechanisms of their specifically high or low expression remain to be revealed and explained urgently. SEGreg is a comprehensive database containing SEGs identified by our SEGtool from four high-throughput datasets of different cancers/tissues/cell lines (TCGA, BodyMap, CCLE and GTEx), along with their corresponding miRNA and TF regulations collected from several databases. SEGreg will provide useful clues to reveal the functions and regulations of SEGs','Database of specifically expressed genes and regulation',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('semimags','SemiMAGs','https://semimags.netlify.app/','GET','SemiMAGs is an online resource for Metagenome-Assembled Genomes (MAGs) based on PacBio HiFi sequencing technology.','SemiMAGs is an online resource for Metagenome-Assembled Genomes (MAGs) based on PacBio HiFi sequencing technology.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('sesbaniaomics','SesbaniaOmics','https://ngdc.cncb.ac.cn/sesbaniaomics','GET',NULL,'SesbaniaOmics is a specialized multi-omics database for Sesbania plants, integrating genomic, transcriptomic, proteomic, epigenomic, and phenotypic data. This resource supports research on salt-tolerance mechanisms, enabling genetic improvement and molecular breeding of stress-resistant crops. By providing comprehensive biological data, SesbaniaOmics facilitates sustainable agriculture in saline-affected regions, addressing global soil salinization challenges.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('SNP2APA','SNP2APA','http://gong_lab.hzau.edu.cn/SNP2APA/','GET','A database to evaluate the effects of SNPs on APA events.','A database to evaluate the effects of SNPs on APA events',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('spencer','SPENCER','https://spencer.renlab.org/','GET','SPENCER is a catalog of small peptides encoded by ncRNAs. The ncRNA encoding peptides were derived from re-annotation of public mass spectrometry data from over 1,700 patient samples spanning diverse cancers. SPENCER enables the users to simply and clearly explore differential expression of ncRNA peptides of interest in different cancer patients. In addition, SPENCER is also a powerful platform for querying the immunogenicity of peptides encoded by ncRNAs.','A comprehensive database for small peptides encoded by ncRNA in cancer patients',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('Taxonomy','Taxonomy','https://www.ncbi.nlm.nih.gov/taxonomy','GET',NULL,'The Taxonomy Database is a curated classification and nomenclature for all of the organisms in the public sequence databases. This currently represents about 10% of the described species of life on the planet.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('vcgdb','VCG','http://vcg.cbi.ac.cn/','GET','VCGDB is a big data solution based on public data released by 1000 Genomes Project.','Virtual Chinese Genome Database is a dynamic genome database of Chinese population.',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('vfdb','VFDB','http://www.mgc.ac.cn/VFs/','GET','VFDB is a comprehensive knowledge base and a versatile analysis platform for bacterial virulence factors.','Virulence Factor Database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('weram','WERAM','http://weram.biocuckoo.org/','GET','WERAM 1.0 is a comprehensive Eukaryotic Writers, Erasers and Readers protein of Histone Acetylation and Methylation system Database for 148 eukaryotic species. Totally, WERAM database contained more than 20 thousand nonredundant histone regulators from 148 eukaryotes. The detailed annotations and classification information of histone regulators were provided, together with site-specific histone substrates if available.','Eukaryotic Writers, Erasers and Readers protein of Histone Acetylation and Methylation system Database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('ZCURVE_CoVdb','ZCURVE_CoVdb','http://tubic.tju,edu.cn/CoVdb/','GET',NULL,'Database of Essential Genes',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
INSERT INTO database_resource (db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES ('π-omicskit','π-OmicsKit','https://ngdc.cncb.ac.cn/piomicskit/home','GET',NULL,'π-OmicsKit  is an expert-curated resource for reproducible primary processing of omics data. It currently provides 80 ready-to-run kits covering DNA-, RNA- and protein-level measurements across bulk, single-cell, long-read and spatial assays. ',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
