','Molecular Module Database',1,'ENABLED','SYSTEM','SYSTEM') ON DUPLICATE KEY UPDATE name=VALUES(name),db_url=VALUES(db_url),db_en_description=VALUES(db_en_description),db_en_title=VALUES(db_en_title),update_by='SYSTEM';
